"""data/world.json → relay/plans.mjs (수도 등 시험 플랜 코스 목록). 손으로 고치지 않는다.

    python3 tools/build_plans.py
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
world = json.loads((root / 'data' / 'world.json').read_text())

# Capital (서울) 코스 26개
seoul = next(r for c in world['countries'] if c['id'] == 'KR' for r in c['regions'] if r['id'] == 'seoul')
capital_courses = seoul['courses']

lines = [
    '/* generated by tools/build_plans.py — 시험 플랜 코스 목록. 손으로 고치지 않는다. */',
    'export const CAPITAL_COURSES = ' + json.dumps(capital_courses, indent=2, ensure_ascii=False) + ';',
    '',
    'export const PLANS = {',
    '  capital: CAPITAL_COURSES,',
    '};',
]

(root / 'relay' / 'plans.mjs').write_text('\n'.join(lines) + '\n')
print(f'Capital plan: {len(capital_courses)} courses → relay/plans.mjs')
